"""Structured evidence for a price-shock investigation, generated by fixed rules from computed results.

Five layers, kept apart on purpose:

* **Observed facts**: what the stored observations say directly (prices, months, gaps).
* **Quantitative descriptions**: statistics computed from them (changes, ranks, comparisons with other markets).
* **Possible mechanisms**: a fixed list of economically plausible explanations. For each, the rules state
  what the available data show, whether that is *consistent with* the mechanism, *argues against* it, or
  whether it *cannot be assessed* because the necessary data are not integrated. "Consistent with" is never
  "caused by": several mechanisms can be consistent with the same evidence.
* **Evidence gaps**: the information that would be needed to discriminate between mechanisms.
* **Unsupported conclusions**: claims a reader might be tempted to draw that this evidence cannot establish.

Every statement carries its inference type: ``descriptive`` (what the data are), ``associational`` (things
that occurred together), ``predictive`` or ``causal``. Nothing here is ever stated as causal. No language model
is involved; the same configuration always produces the same text.
"""

from __future__ import annotations

from typing import Any

import pandas as pd

from market_almanac.analytics.shocks import MIN_REFERENCE, Z_ELEVATED

STATUS_TEXT = {
    "consistent": "Consistent with the available evidence",
    "partly_consistent": "Partly consistent with the available evidence",
    "less_likely": "The available evidence argues against this being the main explanation",
    "not_indicated": "Not indicated by the available evidence",
    "context_only": "Only contextual data are available; not evaluated",
    "cannot_be_assessed": "Cannot be assessed with the data integrated here",
}


def pct(v: float | None, signed: bool = True, digits: int = 1) -> str:
    if v is None:
        return "n/a"
    s = f"{v * 100:+.{digits}f}%" if signed else f"{abs(v) * 100:.{digits}f}%"
    return s


def month_name(ym: str | None) -> str:
    return pd.Timestamp(f"{ym[:7]}-01").strftime("%B %Y") if ym else "n/a"


def money(v: float | None, cur: str, unit: str) -> str:
    if v is None:
        return "n/a"
    return f"{v:,.0f} {cur}/{unit}" if v >= 100 else f"{v:,.2f} {cur}/{unit}"


def _st(text: str, kind: str = "descriptive", keys: list[str] | None = None) -> dict[str, Any]:
    return {"text": text, "inference": kind, "evidence": keys or []}


def observed_facts(doc: dict[str, Any]) -> list[dict[str, Any]]:
    s, mg, q = doc["subject"], doc["magnitude"], doc["observation_quality"]
    cur, unit = str(s["currency"]), str(s["unit"])
    out = []
    ev = doc["config"]["event"]
    if mg["event_price"] is not None:
        out.append(
            _st(
                f"The reported {str(s['price_type']).lower()} price of {s['commodity_name']} in {s['market_name']} for "
                f"{month_name(ev)} was {money(mg['event_price'], cur, unit)} (nominal, {cur}).",
                keys=["magnitude.event_price"],
            )
        )
    else:
        out.append(_st(f"No valid price was reported for {month_name(ev)}.", keys=["magnitude.event_price"]))
    b = mg.get("baseline")
    if b:
        out.append(
            _st(
                f"Over the {b['n']} observed months from {month_name(b['start'])} to {month_name(b['end'])} the price "
                f"averaged {money(b['mean_price'], cur, unit)}.",
                keys=["magnitude.baseline"],
            )
        )
    if doc["episode"] and mg.get("peak_price") is not None:
        out.append(
            _st(
                f"The highest 12-month change in the episode came in {month_name(mg['peak_month'])}, at a price of "
                f"{money(mg['peak_price'], cur, unit)}."
                if doc["direction"] == "up"
                else f"The largest 12-month fall in the episode came in {month_name(mg['peak_month'])}, at a price of "
                f"{money(mg['peak_price'], cur, unit)}.",
                keys=["magnitude.peak_price"],
            )
        )
    out.append(
        _st(
            f"In the investigation window ({month_name(doc['config']['window']['start'])} to "
            f"{month_name(doc['config']['window']['end'])}) {q['months_observed']} of {q['months_in_window']} months "
            f"have a valid price; the longest run of missing months is {q['longest_gap_months']}.",
            keys=["observation_quality"],
        )
    )
    if q.get("records_not_used"):
        out.append(
            _st(
                f"{q['records_not_used']} stored records in the window were not used (invalid, conflicting or "
                "duplicate reports).",
                keys=["observation_quality.flagged_records"],
            )
        )
    return out


def quantitative(doc: dict[str, Any]) -> list[dict[str, Any]]:
    out = []
    mg, un, ep = doc["magnitude"], doc["unusualness"], doc["episode"]
    ev = month_name(doc["config"]["event"])
    if mg["event_yoy_pct"] is not None:
        out.append(
            _st(
                f"The 12-month change to {ev} was {pct(mg['event_yoy_pct'])}"
                + (
                    f"; the change from the previous month was {pct(mg['event_mom_pct'])}."
                    if mg["event_mom_pct"] is not None
                    else "."
                ),
                keys=["magnitude.event_yoy_pct", "magnitude.event_mom_pct"],
            )
        )
    if mg.get("change_from_baseline_pct") is not None:
        out.append(
            _st(
                f"The {ev} price was {pct(mg['change_from_baseline_pct'])} relative to its average over the 12 months "
                "before the movement began (price index "
                f"{100 * (1 + mg['change_from_baseline_pct']):.0f}, baseline = 100).",
                keys=["magnitude.change_from_baseline_pct"],
            )
        )
    if un["status"] == "ok":
        rank = un["percentile"]
        above = f"higher than {rank * 100:.0f}%" if doc["direction"] == "up" else f"lower than {(1 - rank) * 100:.0f}%"
        out.append(
            _st(
                f"Compared with the {un['n_reference']} earlier 12-month changes of this series (from "
                f"{un['reference_years']} calendar years, ending {month_name(un['reference_ends'])}), it was {above} "
                f"of them (robust z-score {un['z']:+.1f}; a typical 12-month change here was "
                f"{pct(un['reference_median_yoy_pct'])}, and 80% fell between {pct(un['reference_p10_yoy_pct'])} and "
                f"{pct(un['reference_p90_yoy_pct'])}).",
                keys=["unusualness"],
            )
        )
        if mg["large_nominal"] and un["label"] == "typical":
            out.append(
                _st(
                    "The change is large in nominal terms but not unusual for this market: changes of this size are "
                    "part of its normal history (for example under persistent inflation).",
                    keys=["unusualness", "magnitude.large_nominal"],
                )
            )
        if not un.get("stable"):
            out.append(
                _st(
                    f"The reference holds fewer than 60 earlier changes, so the rank and z-score may shift as more "
                    "history accumulates. Consecutive 12-month changes overlap, so the number of independent years is "
                    f"about {un['reference_years']}.",
                    keys=["unusualness.n_reference"],
                )
            )
    else:
        out.append(_st(f"Whether the movement was unusual is not assessed: {un['text']}.", keys=["unusualness"]))
    if ep:
        if ep["kind"] == "unusual":
            out.append(
                _st(
                    f"The 12-month change met the episode rule (|z| >= {Z_ELEVATED:g}) from {month_name(ep['start'])} "
                    f"to {month_name(ep['end'])} ({ep['duration_months']} months"
                    + (", and it was still elevated at the last observation" if ep["ongoing"] else "")
                    + ").",
                    keys=["episode", "persistence"],
                )
            )
        if ep.get("retrace_6m_pct") is not None:
            out.append(
                _st(
                    f"Six months after the peak the price was {pct(ep['retrace_6m_pct'])} relative to the peak.",
                    keys=["episode.retrace_6m_pct"],
                )
            )
    se = doc["seasonality"]
    if se.get("status") == "ok" and se.get("observed_change_pct") is not None:
        out.append(
            _st(
                f"The usual seasonal pattern (from {se['years_used']} earlier years) implies a change of "
                f"{pct(se['expected_change_pct'])} from {month_name(se['base_month'])[:-5]} to "
                f"{month_name(se['peak_month'])[:-5]}; the observed change over those months was "
                f"{pct(se['observed_change_pct'])}.",
                keys=["seasonality"],
            )
        )
    px = doc["peers"]["extent"]
    if px["n_peers"]:
        if px["class"] == "inconclusive":
            out.append(
                _st(
                    f"Only {px['n_assessable']} of {px['n_peers']} comparable markets (same commodity, unit, price "
                    "type "
                    "and currency) could be assessed at that time, too few to judge whether the movement was shared.",
                    keys=["peers.extent"],
                )
            )
        else:
            out.append(
                _st(
                    f"{px['n_elevated']} of {px['n_assessable']} assessable comparable markets were also unusually "
                    f"{'high' if doc['direction'] == 'up' else 'low'} within a month of the peak (median 12-month "
                    f"change across comparable markets {pct(px['median_peer_yoy_pct'])}).",
                    "associational",
                    keys=["peers.extent"],
                )
            )
    else:
        out.append(
            _st("No other market reports this commodity in the same unit, price type and currency.", keys=["peers"])
        )
    br = doc["breadth"]["extent"]
    if br["n_peers"] and br["class"] != "inconclusive":
        out.append(
            _st(
                f"In the same market, {br['n_elevated']} of {br['n_assessable']} other assessable foods were also "
                f"unusually {'high' if doc['direction'] == 'up' else 'low'} at the same time.",
                "associational",
                keys=["breadth.extent"],
            )
        )
    mac = doc["context"]["macro"]
    if mac.get("cpi"):
        out.append(
            _st(
                f"The national consumer price index rose {pct(mac['cpi']['yoy_pct'])} over the same 12 months "
                f"({mac['cpi']['provider'].upper()}); deflated by it, the commodity's 12-month change was "
                f"{pct(mac['real_yoy_pct'])}.",
                keys=["context.macro.cpi"],
            )
        )
    if mac.get("fx"):
        fx = mac["fx"]["yoy_pct"]
        out.append(
            _st(
                f"The local currency's exchange rate to the US dollar changed {pct(fx)} over the same 12 months "
                f"({'more units per dollar: depreciation' if fx > 0 else 'fewer units per dollar: appreciation'}).",
                keys=["context.macro.fx"],
            )
        )
    return out


def _mechanisms(doc: dict[str, Any]) -> list[dict[str, Any]]:
    ep, px, br = doc["episode"], doc["peers"]["extent"], doc["breadth"]["extent"]
    se, wx, mac = doc["seasonality"], doc["context"]["weather"], doc["context"]["macro"]
    per = doc["persistence"]
    flags = set(ep["flags"]) if ep else set()
    up = doc["direction"] == "up"
    out: list[dict[str, Any]] = []

    def add(key: str, name: str, desc: str, status: str, evidence: list[str], needed: list[str]) -> None:
        out.append(
            {
                "key": key,
                "name": name,
                "description": desc,
                "status": status,
                "status_text": STATUS_TEXT[status],
                "evidence": evidence,
                "needed": needed,
            }
        )

    # 1. data problems
    ev_rep: list[str] = []
    if "implausible_jump" in flags:
        ev_rep.append("the price changed by more than a factor of four within a single month")
    if "single_month_reversed" in flags:
        ev_rep.append("the movement lasted one month and reversed the following month")
    if doc["observation_quality"].get("records_not_used"):
        ev_rep.append(
            f"{doc['observation_quality']['records_not_used']} records in the window were invalid or conflicting"
        )
    if ev_rep:
        status = "consistent"
    elif per.get("verdict") in ("persistent", "ongoing") and px["class"] in ("widespread", "mixed"):
        status = "less_likely"
        ev_rep.append("the movement persisted for several months and was shared by other markets")
    else:
        status = (
            "partly_consistent" if px["class"] == "local" and per.get("verdict") == "single_month" else "not_indicated"
        )
        ev_rep.append("no implausible jumps or reversing single-month spikes were detected")
    add(
        "data_error",
        "Recording, unit or measurement error",
        "A change of unit, a mis-keyed price or a change of reporting outlet can look like a price shock.",
        status,
        ev_rep,
        ["the original survey records or enumerator notes", "confirmation of the unit and outlet by the data provider"],
    )

    # 2. seasonality
    if se.get("status") != "ok":
        s_status, s_ev = "cannot_be_assessed", [f"no seasonal profile ({se.get('note', 'too few complete years')})"]
    else:
        v = se.get("verdict")
        s_status = {"largely_seasonal": "consistent", "partly_seasonal": "partly_consistent"}.get(v, "less_likely")
        share = se.get("share_explained")
        s_ev = [
            f"the usual seasonal pattern implies {pct(se['expected_change_pct'])} over these months against "
            f"{pct(se.get('observed_change_pct'))} observed"
            + (f" (about {share * 100:.0f}% of the rise in log terms)" if share is not None else ""),
            "the unusualness test compares 12-month changes, which already removes a regular seasonal pattern",
        ]
    add(
        "seasonal",
        "Normal seasonal pattern (lean season, harvest timing)",
        "Prices of many staples rise every year before the harvest and fall after it.",
        s_status,
        s_ev,
        ["the local crop calendar and the timing of the most recent harvest"],
    )

    # 3. country-wide driver for this commodity
    c_ev = [
        f"{px['n_elevated']} of {px['n_assessable']} assessable comparable markets were unusually "
        f"{'high' if up else 'low'} at the same time"
        if px["n_assessable"]
        else "no comparable market could be assessed"
    ]
    c_status = {
        "widespread": "consistent",
        "mixed": "partly_consistent",
        "local": "less_likely",
        "inconclusive": "cannot_be_assessed",
    }[px["class"]]
    add(
        "national_commodity",
        "Country-wide supply or demand change for this commodity (harvest shortfall, import or trade disruption)",
        "A shock to national supply or demand moves the price in most markets that trade the commodity.",
        c_status,
        c_ev,
        [
            "national production estimates for the relevant season (not integrated)",
            "import, export and cross-border trade flows (not integrated)",
        ],
    )

    # 4. local disruption
    if px["class"] == "local":
        l_status = "consistent" if per.get("verdict") in ("persistent", "ongoing", "short") else "partly_consistent"
    elif px["class"] == "widespread":
        l_status = "less_likely"
    elif px["class"] == "mixed":
        l_status = "partly_consistent"
    else:
        l_status = "cannot_be_assessed"
    add(
        "local_disruption",
        "Local supply or market-access disruption (transport, insecurity, market closure)",
        "A disruption that affects one market or area raises prices there but not elsewhere.",
        l_status,
        [c_ev[0], f"the episode lasted {ep['duration_months']} months" if ep else "no episode was detected"],
        [
            "conflict and access-constraint records for the area (not integrated)",
            "transport costs and road or border closures (not integrated)",
        ],
    )

    # 5. general inflation / currency
    m_ev: list[str] = []
    if br["class"] != "inconclusive":
        m_ev.append(
            f"{br['n_elevated']} of {br['n_assessable']} other assessable foods in the same market were also unusually "
            f"{'high' if up else 'low'}"
        )
    if mac.get("cpi"):
        m_ev.append(f"national CPI changed {pct(mac['cpi']['yoy_pct'])} over the same 12 months")
    if mac.get("fx"):
        m_ev.append(f"the exchange rate to the US dollar changed {pct(mac['fx']['yoy_pct'])}")
    yoy = doc["magnitude"]["event_yoy_pct"]
    if mac.get("cpi") and yoy:
        share = mac["cpi"]["yoy_pct"] / yoy if yoy else 0
        g_status = "consistent" if share >= 0.5 else "partly_consistent" if share >= 0.2 else "less_likely"
    elif br["class"] == "broad":
        g_status = "consistent"
    elif br["class"] == "mixed":
        g_status = "partly_consistent"
    elif br["class"] == "narrow":
        g_status = "less_likely"
    else:
        g_status = "cannot_be_assessed"
    if not mac.get("cpi"):
        m_ev.append("no consumer price index is integrated for this country")
    if not mac.get("fx"):
        m_ev.append("no exchange-rate series is integrated for this country")
    add(
        "macro",
        "General inflation or currency depreciation",
        "When the currency loses value or inflation is high, most prices rise together, imported foods first.",
        g_status,
        m_ev,
        ["monthly consumer price index and exchange rate for the country (integrated only where listed above)"],
    )

    # 6. weather / production
    pr = wx.get("production_region")
    cell = wx.get("market_cell")
    w_ev = []
    if pr:
        w_ev.append(
            f"seasonal rainfall in the {pr['crop']}-growing areas had a standardised anomaly of "
            f"{pr['season_rain_anomaly_z']:+.1f} as of {month_name(pr['period'])}"
        )
    if cell and cell.get("mean_rain_anomaly_z") is not None:
        w_ev.append(
            f"rainfall at the market's grid cell averaged a standardised anomaly of {cell['mean_rain_anomaly_z']:+.1f} "
            f"over the 12 months to {month_name(cell['window']['end'])}"
        )
    add(
        "weather",
        "Weather-related production shock (drought, floods)",
        "Poor rains in producing areas can reduce harvests and raise prices months later.",
        "context_only" if w_ev else "cannot_be_assessed",
        w_ev
        + (
            [
                "these are measurements placed alongside the prices; they were not evaluated as an explanation "
                "for this "
                "event"
            ]
            if w_ev
            else ["no weather data are integrated for this market or crop"]
        ),
        ["harvest outcome for the season (not integrated)", "evidence that this market is supplied from those areas"],
    )

    add(
        "policy",
        "Policy intervention (export ban, tariff, subsidy removal, price control)",
        "Trade and price policies can move domestic prices abruptly.",
        "cannot_be_assessed",
        ["no record of policy measures is integrated"],
        ["dated records of trade and price policy measures for the country"],
    )
    add(
        "international",
        "Transmission of international prices",
        "Prices of imported or traded staples follow world markets with a lag.",
        "cannot_be_assessed",
        ["no international reference prices are integrated"],
        ["world reference prices for the commodity and the country's import dependence"],
    )
    return out


def _unsupported(doc: dict[str, Any]) -> list[dict[str, Any]]:
    px = doc["peers"]["extent"]
    out = [
        _st(
            "That any of the mechanisms above caused this movement. The evidence can be consistent or inconsistent "
            "with a mechanism; it does not identify causes.",
            "causal",
        ),
        _st(
            "That households faced food insecurity, hunger or a crisis. Prices alone do not measure incomes, "
            "access or consumption, and no risk score is computed here.",
            "causal",
        ),
        _st(
            "That the price will continue to rise or fall back. No forecast is made in this investigation.",
            "predictive",
        ),
    ]
    if px["class"] in ("local", "inconclusive"):
        out.append(_st("That prices of this commodity rose across the country.", "descriptive"))
    if px["class"] == "widespread":
        out.append(
            _st(
                "That the same factor drove every market's movement. Shared timing is consistent with a common cause "
                "but does not establish one.",
                "causal",
            )
        )
    if doc["context"]["weather"].get("status") == "ok":
        out.append(
            _st(
                "That rainfall explains the movement. Weather is shown as context only, it was not evaluated for this "
                "event, and Market Almanac's pre-registered studies did not establish that it improves price "
                "forecasts.",
                "causal",
            )
        )
    if not doc["context"]["macro"].get("cpi"):
        out.append(
            _st(
                "How much purchasing power changed. Prices are nominal and no consumer price index is integrated for "
                "this country, so the real change cannot be computed.",
                "descriptive",
            )
        )
    return out


def _gaps(mechanisms: list[dict[str, Any]]) -> list[str]:
    seen: list[str] = []
    for m in mechanisms:
        for n in m["needed"]:
            if n not in seen:
                seen.append(n)
    return seen


def conclusion(doc: dict[str, Any], mechanisms: list[dict[str, Any]]) -> dict[str, Any]:
    """The bottom line, assembled from the classifications (descriptive and associational only)."""
    s, un, mg, ep = doc["subject"], doc["unusualness"], doc["magnitude"], doc["episode"]
    px, br, per = doc["peers"]["extent"], doc["breadth"]["extent"], doc["persistence"]
    verb = "risen" if doc["direction"] == "up" else "fallen"
    hl = "high" if doc["direction"] == "up" else "low"
    parts = []
    lead = (
        f"In {month_name(doc['config']['event'])} the price of {s['commodity_name']} in {s['market_name']} had {verb} "
        f"{pct(mg['event_yoy_pct'], signed=False)} over 12 months"
        if mg["event_yoy_pct"] is not None
        else f"No 12-month change can be computed for {s['commodity_name']} in {s['market_name']} in "
        f"{month_name(doc['config']['event'])}"
    )
    if un["status"] == "ok":
        parts.append(
            lead
            + (
                f", which is unusual for this market (robust z {un['z']:+.1f}; beyond "
                f"{(un['percentile'] if doc['direction'] == 'up' else 1 - un['percentile']) * 100:.0f}% of "
                f"{un['n_reference']} earlier 12-month changes)."
                if un["label"] == "unusual"
                else f", which is within the usual range for this market (robust z {un['z']:+.1f})."
            )
        )
    else:
        parts.append(lead + f". Whether that is unusual cannot be assessed: {un['text']}.")
    if ep and ep["kind"] == "unusual":
        parts.append(
            {
                "single_month": "The unusual change lasted a single month.",
                "short": f"It lasted {ep['duration_months']} months.",
                "persistent": f"It persisted for {ep['duration_months']} months.",
                "ongoing": f"It has lasted {ep['duration_months']} months and was still elevated at the last "
                "observation.",
            }.get(per["verdict"], "")
        )
    parts.append(
        {
            "widespread": f"Most comparable markets in the country were also unusually {hl} at the time.",
            "mixed": f"Some comparable markets were also unusually {hl}; others were not.",
            "local": f"Few comparable markets were unusually {hl} at the time.",
            "inconclusive": "Too few comparable markets could be assessed to tell whether the movement was local.",
        }[px["class"]]
    )
    parts.append(
        {
            "broad": f"Most other foods in the same market were also unusually {hl}.",
            "mixed": f"Some other foods in the same market were also unusually {hl}.",
            "narrow": "Few other foods in the same market moved unusually.",
            "inconclusive": "Too few other foods in the same market could be assessed.",
        }[br["class"]]
    )
    consistent = [m["name"].split(" (")[0].lower() for m in mechanisms if m["status"] == "consistent"]
    unknown = [m["name"].split(" (")[0].lower() for m in mechanisms if m["status"] == "cannot_be_assessed"]
    if consistent:
        parts.append(
            "This pattern is consistent with " + _join(consistent, "or") + ", but the data integrated here cannot "
            "establish which, if any, was responsible."
        )
    else:
        parts.append("None of the mechanisms that can be checked here is clearly supported by the available data.")
    if unknown:
        parts.append("It cannot assess " + _join(unknown, "or") + ".")
    if ep and ep.get("data_concern"):
        parts.append(
            "The record shows signs of a possible recording or unit change; verify the observations before relying "
            "on them."
        )
    return {
        "text": " ".join(p for p in parts if p),
        "inference": "descriptive and associational; no causal claim",
    }


def _join(items: list[str], word: str) -> str:
    return items[0] if len(items) == 1 else ", ".join(items[:-1]) + f" {word} " + items[-1]


def build_evidence(doc: dict[str, Any]) -> dict[str, Any]:
    mechanisms = _mechanisms(doc)
    return {
        "observed_facts": observed_facts(doc),
        "quantitative": quantitative(doc),
        "mechanisms": mechanisms,
        "gaps": _gaps(mechanisms),
        "unsupported": _unsupported(doc),
        "conclusion": conclusion(doc, mechanisms),
        "assessment": assessment(doc),
        "rules": {
            "unusual": f"|robust z| >= {Z_ELEVATED:g} against at least {MIN_REFERENCE} earlier 12-month changes",
            "statuses": STATUS_TEXT,
        },
    }


def assessment(doc: dict[str, Any]) -> list[dict[str, Any]]:
    """The at-a-glance verdicts: magnitude, unusualness, persistence, extent, breadth, seasonality, data."""
    un, mg, per, se = doc["unusualness"], doc["magnitude"], doc["persistence"], doc["seasonality"]
    px, br, ep = doc["peers"]["extent"], doc["breadth"]["extent"], doc["episode"]
    q = doc["observation_quality"]
    cards = [
        {
            "key": "magnitude",
            "label": "12-month change",
            "value": pct(mg["event_yoy_pct"]),
            "tone": "neutral",
            "detail": "large in nominal terms" if mg["large_nominal"] else "nominal, local currency",
        },
        {
            "key": "unusualness",
            "label": "Unusual for this market?",
            "value": ("Yes" if un["label"] == "unusual" else "No") if un["status"] == "ok" else "Not assessed",
            "tone": ("warn" if un["label"] == "unusual" else "good") if un["status"] == "ok" else "muted",
            "detail": f"robust z {un['z']:+.1f}, {un['n_reference']} earlier changes"
            if un["status"] == "ok"
            else un["text"],
        },
        {
            "key": "persistence",
            "label": "Persistence",
            "value": {
                "single_month": "One month",
                "short": f"{per.get('duration_months')} months",
                "persistent": f"{per.get('duration_months')} months",
                "ongoing": "Ongoing",
                "no_episode": "No episode",
            }[per["verdict"]],
            "tone": "neutral" if per["verdict"] != "no_episode" else "muted",
            "detail": f"{month_name(ep['start'])} to {month_name(ep['end'])}"
            if ep
            else "no month met the episode rule",
        },
        {
            "key": "extent",
            "label": "Other markets",
            "value": {"widespread": "Widespread", "mixed": "Mixed", "local": "Local", "inconclusive": "Inconclusive"}[
                px["class"]
            ],
            "tone": "muted" if px["class"] == "inconclusive" else "neutral",
            "detail": f"{px['n_elevated']} of {px['n_assessable']} assessable comparable markets also unusual"
            if px["n_assessable"]
            else f"{px['n_peers']} comparable markets, none assessable",
        },
        {
            "key": "breadth",
            "label": "Other foods, same market",
            "value": {"broad": "Broad", "mixed": "Mixed", "narrow": "Narrow", "inconclusive": "Inconclusive"}[
                br["class"]
            ],
            "tone": "muted" if br["class"] == "inconclusive" else "neutral",
            "detail": f"{br['n_elevated']} of {br['n_assessable']} assessable foods also unusual"
            if br["n_assessable"]
            else "no other food could be assessed",
        },
        {
            "key": "seasonality",
            "label": "Seasonal?",
            "value": {
                "largely_seasonal": "Largely",
                "partly_seasonal": "Partly",
                "not_seasonal": "No",
                "no_base_observation": "Not assessed",
            }.get(se.get("verdict", ""), "Not assessed"),
            "tone": "muted" if se.get("status") != "ok" else "neutral",
            "detail": f"usual pattern implies {pct(se['expected_change_pct'])} over these months"
            if se.get("status") == "ok"
            else str(se.get("note") or "no episode to compare"),
        },
        {
            "key": "data",
            "label": "Data quality",
            "value": "Concerns"
            if (ep and ep.get("data_concern")) or q["months_missing"] > q["months_in_window"] / 3
            else "Adequate",
            "tone": "warn"
            if (ep and ep.get("data_concern")) or q["months_missing"] > q["months_in_window"] / 3
            else "good",
            "detail": f"{q['months_observed']} of {q['months_in_window']} months observed"
            + ("; possible recording or unit change" if ep and ep.get("data_concern") else ""),
        },
    ]
    return cards
